param([string]$Python="python",[string]$RuntimeRoot="",[switch]$InstallTooling,[switch]$SetupWindowsML,[switch]$SetupSpeech,[switch]$SetupTTS,[switch]$SetupCleanup,[switch]$Build,[switch]$Validate,[switch]$AllRuntimes)
$ErrorActionPreference='Stop';if($env:OS-ne'Windows_NT'){throw'Windows required'};$Root=Split-Path -Parent $PSScriptRoot;if(-not$RuntimeRoot){$RuntimeRoot=Join-Path $env:LOCALAPPDATA 'Metatron'};New-Item -ItemType Directory -Force $RuntimeRoot|Out-Null;if($InstallTooling){if(-not(Get-Command winget -ErrorAction SilentlyContinue)){throw'winget required'};foreach($id in @('Git.Git','Python.Python.3.12','OpenJS.NodeJS.LTS','Rustlang.Rustup')){winget install --id $id --exact --accept-package-agreements --accept-source-agreements --silent --disable-interactivity}};& $PSScriptRoot\Test-WindowsPrerequisites.ps1 -Python $Python -OutputJson (Join-Path $RuntimeRoot 'preflight.json') -RequireDevTools;if($LASTEXITCODE-ne0){exit $LASTEXITCODE};if($AllRuntimes){$SetupWindowsML=$SetupSpeech=$SetupTTS=$SetupCleanup=$true};if($SetupWindowsML){& $PSScriptRoot\Setup-WindowsML.ps1 -Root (Join-Path $RuntimeRoot 'runtimes\winml') -Python $Python};if($SetupSpeech){& $PSScriptRoot\Setup-SpeechRuntime.ps1 -EngineRoot (Join-Path $RuntimeRoot 'engines\EZSTT') -Python $Python};if($SetupTTS){& $PSScriptRoot\Setup-Kokoro-TTS.ps1 -Root $RuntimeRoot -Python $Python -Precision fp16};if($SetupCleanup){& $PSScriptRoot\Setup-S1Mini.ps1 -Root (Join-Path $RuntimeRoot 's1-mini') -Python $Python};if($Build){& $PSScriptRoot\Build-Windows.ps1 -Python $Python};if($Validate){& $PSScriptRoot\Invoke-MetatronFullValidation.ps1 -Python $Python -All -SupportBundle;if($LASTEXITCODE-ne0){exit $LASTEXITCODE}}
